public enum Layer {
    /// The hub band's slot under the bar: over the page column it opens above, its shadow on the page.
    public static let layerBand: Double = 20
    /// The phone's edge-pull strip (EdgePull): over the page at the screen's edge, so a press there is the pull's; under a canvas stage.
    public static let layerPull: Double = 30
    /// A canvas stage (CanvasStages: the artifact's frame portalled to the body over its slot): over the page and the edge pull, under a docked composer and the bar.
    public static let layerStage: Double = 40
    /// A docked composer, or what stands in its place (Composer's dock, the decision page's and the view bar's docks, the project panel's no-composer note): over the transcript and its fades.
    public static let layerDock: Double = 50
    /// The top bar floating over a phone's tab row: over the dock and everything in the page under it.
    public static let layerBar: Double = 60
    /// A toolbar fixed over the page (the task board's bulk bar): over the bar and the dock, under the phone's preview sheet.
    public static let layerToolbar: Double = 70
    /// A phone's sheet that is part of the page, holding nothing (no scrim, the page above it live): the preview sheet host (SideSheet) and Caw's panel on a project's page (CawFloat). Over every page layer, under the floating surfaces, so a menu or a sheet opened from the page stands over it.
    public static let layerSheet: Double = 80
    /// A canvas stage standing in the phone's preview sheet: just over the sheet it stands in.
    public static let layerSheetStage: Double = 90
    /// A motion bench laid over the whole shell: over every page layer, under the floating surfaces its own controls open.
    public static let layerBench: Double = 100
    /// The toast layer while the burger's sheet is open: under the sheet's scrim, so a toast waits dimmed and never paints over the open navigation.
    public static let layerToastHeld: Double = 110
    /// Every floating surface: the kit's popover, menu, submenu, select, tooltip, dialog, sheet, drawer and their scrims, the details and lead cards, a hover panel, Files' floating panel, the lightbox. They belong in the browser's top layer; bits-ui portals them to the body instead, so they share this one role and the one opened last stands over the one it opened from.
    public static let layerFloat: Double = 120
    /// A copy in flight between two places on the page (queued words to the field, a chip to its card, a preview closing into its row): over everything it crosses, floating surfaces included.
    public static let layerFlight: Double = 130
    /// A motion bench's own switches: over the floating surfaces the bench opens, so they stay pressable while one is open.
    public static let layerBenchControls: Double = 140
    /// The skip link, shown on focus: over the shell and everything in it.
    public static let layerSkip: Double = 150
    /// The toast layer: over every surface on the page, a dialog included.
    public static let layerToast: Double = 160
    /// The screen's edge strips (ScreenEdges) Safari takes its bar colour from: over every layer, toasts included, since a strip is the colour of whatever stands on its edge and is never seen as itself.
    public static let layerScreenEdge: Double = 170
}

public enum Effect {
    /// How much of the page's own background the scrim lays over what is under it: its alpha. The screen's edges under an open scrim (ScreenEdges) mix the same share of background into the edge colour, so the strip Safari extends is the scrim's colour over that edge.
    public static let scrimMix: Double = 0.72
    /// A message not yet said in the conversation (sending, queued).
    public static let ghostPresence: Double = 0.7
    public static let materialSaturate: Double = 1.6
    /// The chosen session tab's rim strength (its opacity, a plain number so the rim's arithmetic can divide by it), on every width, when its session is working, needs you or failed: its top holds 3:1 against the shelf (WCAG non-text contrast) in both themes, and so do its sides at their mid-height, their taper (tab-rim-taper, eased out by tab-rim-taper-ease) whole well before it. Unchosen tabs wear tab-rim-mix-subtle, or no rim when idle.
    /// By day and by night: read it with `value(for:)`.
    public static let tabRimMixChosen = SchemeValue(light: 0.97, dark: 0.78)
    /// The chosen tab's rim strength when its session is idle or done, in the muted ink: its top holds 3:1 against the shelf (3.2:1 by day, 3.8:1 by night at 1px); its sides taper softer by design. By day 0.32 left its side at 1.4:1, by night at 2.0:1.
    /// By day and by night: read it with `value(for:)`.
    public static let tabRimMixIdle = SchemeValue(light: 0.86, dark: 0.54)
    /// An unchosen session tab's rim strength when its session is anything but idle (working, needs you, done, failed): the same outline and taper as the chosen tab's, clearly quieter (owner: other tabs have no rim "unless they are active, then they should have a more subtle rim", "or any other status"). An unchosen idle tab draws no rim. It is a status mark, not a boundary: the tab's card edge is the boundary, so it is not held to 3:1. The owner's tuning on the bench: 0.5 by day and by night ("50pct").
    public static let tabRimMixSubtle: Double = 0.5
    /// A session tab's rim stroke, in px, on every tab, in both themes (1 under Increase Contrast and Reduce Transparency). A plain number for the rim's arithmetic (PaneTabs `.rim`); its shoulders, its feet's narrowing to a point and a gliding seam's stop (`--seam-stroke`) all follow it.
    public static let tabRimWidth: Double = 1
    /// The owner's tuning on the bench ("32"). How far, in px along the stroke, a session tab's rim fades out at each free end (the tips of its feet on the shelf), on every tab, in both themes, so a rim never stops on a hard cut (owner: "the rim should taper-progress-fade at the very edges"). A plain number for the rim's arithmetic (PaneTabs `.rim`); the fade stops short of the shoulders.
    public static let tabRimTaper: Double = 32
    /// The shape of a rim's taper along the stroke from its tip: its ink rises as 1 - (1 - s/tab-rim-taper)^p, an ease-out from the tip, 0 at the tip and full at tab-rim-taper (or at the shoulder, where that comes first). At 6 it is half up 3.5px from the tip and 90% up by 32% of the taper's length (10.2px of 32), so the chosen tab's sides stand whole at their mid-height and hold 3:1 against the shelf, while the faint tail stays at the very tip. A plain number for the rim's arithmetic (PaneTabs `.rim`, as gradient stops through pow()); the stroke's narrowing to a point ends where this curve's ink is 90% whole.
    public static let tabRimTaperEase: Double = 6
}

public enum Motion {
    /// Entrances, exits, colour and any change in place ease out, the default; what is already on screen moving eases in-out; floating surfaces, sheets, page swaps and flights take the drawer curve; constant motion is linear. No ease-in.
    public static let easeOut = TimingCurve(x1: 0.23, y1: 1, x2: 0.32, y2: 1)
    public static let easeInOut = TimingCurve(x1: 0.77, y1: 0, x2: 0.175, y2: 1)
    public static let easeDrawer = TimingCurve(x1: 0.32, y1: 0.72, x2: 0, y2: 1)
    /// Two states trading places where they stand: a folder tab's choice, over --dur-settle (its lean, sheet, title ink and rim travel together); a skeleton's pulse and its reveal. CSS ease-in-out, the curve transitions.dev gives icon and text swaps and its skeleton loader's pulse and reveal (--reveal-ease: ease-in-out). At 400ms its steepest 1/60s frame moves 7.2% of the change; every other house curve moves more than an eighth in one frame there (ease-out 17.6%, ease-in-out 19.7%, ease-drawer 17.2%), which reads as the change lurching.
    public static let easeCrossfade = TimingCurve(x1: 0.42, y1: 0, x2: 0.58, y2: 1)
    /// The last stretch of a steady glide; the glide starts at speed. From the steady pace, speed falling evenly to rest. Only glide() in motion/curves.svelte.ts writes it; no component picks it.
    public static let easeGlideOut = TimingCurve(x1: 0.3333, y1: 0.6667, x2: 0.6667, y2: 1)
    /// Between one row of an opening tree and the next: its line reaches each in turn at a steady pace, one row's room per stagger.
    /// In seconds.
    public static let durStagger: TimeInterval = 0.06
    /// The most an opening tree's line takes to reach its last row: a longer tree's rows come closer together.
    /// In seconds.
    public static let durCascade: TimeInterval = 0.48
    /// The hover ghost following the pointer from row to row.
    /// In seconds.
    public static let durGhost: TimeInterval = 0.08
    /// In seconds.
    public static let durControl: TimeInterval = 0.12
    /// In seconds.
    public static let durMenu: TimeInterval = 0.14
    /// How long the pointer rests on a comment's pill before its peek comes; one within this of the last goes at once (DESIGN.md, A pin's pill).
    /// In seconds.
    public static let durPeek: TimeInterval = 0.3
    /// A switch's knob and a checkbox's tick.
    /// In seconds.
    public static let durToggle: TimeInterval = 0.16
    /// In seconds.
    public static let durExit: TimeInterval = 0.16
    /// A button's width following its label while it works.
    /// In seconds.
    public static let durMorph: TimeInterval = 0.18
    /// A transcript row's place opening, its rail drawing down with it.
    /// In seconds.
    public static let durRail: TimeInterval = 0.18
    /// Fades that carry a state change in place.
    /// In seconds.
    public static let durFade: TimeInterval = 0.2
    /// The longest a transcript that opens on a compaction holds its reveal for Caw's mark to be drawn, so the first frame that shows the list shows him. A bound, not a pace: the list is shown the moment he is ready (about 90ms on a cold load), and at the bound without him. Under --dur-wait-grace, so the hold shows nothing of its own.
    /// In seconds.
    public static let durMarkHold: TimeInterval = 0.2
    /// How long a wait runs before its loading state (Caw at loading or reconnecting) appears; a shorter wait shows its plain surface. NN/g, Response Times: no special feedback is needed for delays under 1.0 second.
    /// In seconds.
    public static let durWaitGrace: TimeInterval = 1
    /// In seconds.
    public static let durPop: TimeInterval = 0.26
    /// In seconds.
    public static let durPanel: TimeInterval = 0.28
    /// A pane card picked up off the deck: the lift's scale, sixty percent of the panel's beat, derived from it the way the breath is.
    /// In seconds.
    public static let durPickUp: TimeInterval = 0.168
    /// The composer growing up out of its pill: into the recall wheel, or by the one row that says a queued message is being edited.
    /// In seconds.
    public static let durGrow: TimeInterval = 0.32
    /// The grown composer folding back into its pill, shorter than its growth.
    /// In seconds.
    public static let durGrowExit: TimeInterval = 0.22
    /// A queued message's words flying between its bubble and the composer field, either way, two copies crossfading on the drawer curve.
    /// In seconds.
    public static let durLift: TimeInterval = 0.34
    /// How long a touch rests on the composer, keyboard down, before the recall wheel comes up under it.
    /// In seconds.
    public static let durPressHold: TimeInterval = 0.38
    /// The existing motion/spring.ts response for non-paging surface settlement. Paging uses UIScrollView's system mechanics. Also a folder tab's choice, on ease-crossfade (the owner's pick, "Slow · 400ms").
    /// In seconds.
    public static let durSettle: TimeInterval = 0.4
    /// A tab track's glide under a mouse wheel: the second spring's response.
    /// In seconds.
    public static let durGlide: TimeInterval = 0.3
    /// How long a done state stays up.
    /// In seconds.
    public static let durHold: TimeInterval = 1.2
    /// One turn of an ambient loop: spinner, pulse, ping.
    /// In seconds.
    public static let durLoop: TimeInterval = 1.2
    /// One pulse of a skeleton while it waits: its opacity from 1 down to --skeleton-pulse-floor and back, on --ease-crossfade, looping until what it stands for arrives. transitions.dev Skeleton loader and reveal, --pulse-dur: 1000ms (the owner's pick: "transitions.dev exactly").
    /// In seconds.
    public static let durSkeletonPulse: TimeInterval = 1
    /// A skeleton handing its place to what it stood for: the skeleton fades out and blurs to --skeleton-reveal-blur while the content fades in out of it, both on --ease-crossfade. transitions.dev Skeleton loader and reveal, --reveal-dur: 400ms.
    /// In seconds.
    public static let durSkeletonReveal: TimeInterval = 0.4
    /// In seconds.
    public static let breath: TimeInterval = 2
    public static let pressScale: Double = 0.97
    /// How far Caw shrinks as he fades out, from any drawing, over --dur-fade on ease-out, and the size a Caw whose status has no drawn enter fades in from, over --dur-pop. Material 3, Easing and duration: exit transitions are faster than enters, 200ms.
    public static let leaveScale: Double = 0.97
    public static let popScale: Double = 0.92
    /// How far each card of a session mark's deck shows below the one in front (SessionMark).
    public static let deckStep: Double = 1.25
    /// How much smaller each deck card is than the one in front: card i is the tile scaled by 1 - 0.11 x i.
    public static let deckShrink: Double = 0.11
    /// How much more of the deck's shade each card behind takes.
    public static let deckShadeStep: Double = 0.2
    /// How far a working session's echo grows from its tile before it has faded (motion/echo).
    public static let echoScale: Double = 1.45
    /// A working session's echo as it leaves the tile.
    public static let echoOpacity: Double = 0.45
    /// The opacity live work breathes down to, half a breath in (the shared `breath` keyframes, app.css). The lowest at which every breather's ink (the status-live glyph, each tool family's ink, the muted ink) holds 3:1 (WCAG 2.2 SC 1.4.11, unrounded) on every surface it stands on: page, raised, recess, recess-deep and well (probe breath-and-head). By day 0.8 (the search tool's ink on recess-deep the floor, 3.13:1); at night 0.58 (the plan tool's ink on raised the floor, 3.14:1).
    /// By day and by night: read it with `value(for:)`.
    public static let breathFloor = SchemeValue(light: 0.8, dark: 0.58)
    /// How far an account's week rim is mixed from its hue toward account-week-toward: a clearly different lightness of the same hue. By day 0.32 (the rim 1.9:1 or more from the disc); at night 0.63, the lowest at which the rim stands 1.8:1 from the disc for every account hue (rose the floor), the rim then 7.9:1 or more on its track.
    /// By day and by night: read it with `value(for:)`.
    public static let accountWeekMix = SchemeValue(light: 0.32, dark: 0.63)
    /// An account whose reading is out of date: its rings and its relay band draw at this opacity, the lowest at which every account hue holds 3:1 against the border-control track it lies on, in both schemes (by day cyan and green set the floor at 0.82, at night rose at 0.80); on the raised surface they hold more.
    public static let accountStaleOpacity: Double = 0.82
    /// The first stretch of its nesting line over which a child's icon fades in as it leaves its parent's (motion/branch).
    public static let rideFade: Double = 14
    /// How far every surface, row or part travels as it comes or goes (DESIGN.md, The Enter Rule): a floating surface or toast from its edge, a list swap's rows sideways, a keyframe's rise.
    public static let popRise: Double = 8
    /// How far a view handing its place to the next along a strip travels as it comes in or goes: a tab switch's transcript and its composer's words, from the side of the tab it came from. A cue of which way it went, not a page turn.
    public static let swapNudge: Double = 40
    /// How soft a fold's content is while it folds shut or opens (Caw's panel: the update's notes, the logins signed in everywhere). transitions-dev Accordion expand: the inner panel cross-blurs 2px as its grid row goes 0fr to 1fr.
    public static let foldBlur: Double = 2
    /// The opacity a skeleton pulses down to, half a pulse in. transitions.dev Skeleton loader and reveal, --pulse-min: 0.5.
    public static let skeletonPulseFloor: Double = 0.5
    /// How soft a skeleton is as it goes and its content as it comes, at the far end of the reveal's cross-fade. transitions.dev Skeleton loader and reveal, --reveal-blur: 2px.
    public static let skeletonRevealBlur: Double = 2
}
